require 'json';require 'digest'
d=File.expand_path(__dir__);sha=->(p){Digest::SHA256.file(p).hexdigest}
variants={'baseline'=>['run.rb',%w[insertion nonscalar dynamic_loop dense_loop]],'no-counter'=>['run-no-counter.rb',%w[insertion nonscalar dynamic_loop dense_loop]],'direct-with-counter'=>['run-direct-with-counter.rb',%w[dynamic_loop dense_loop]],'direct-no-counter'=>['run-direct-no-counter.rb',%w[dynamic_loop dense_loop]]}
rows=[];identities={};totals={allocation:0,semantics:0}
variants.each do |label,(runner,shapes)|
 path=d+'/current-'+label+'/report.json';r=JSON.parse(File.read(path));raise 'Incomplete '+label unless r['status']=='characterized'
 raise 'Runner identity '+label unless r['identities'].any?{|path,hash|File.expand_path(path)==d+'/'+runner&&hash==sha.call(d+'/'+runner)}
 r['identities'].each{|p,h|raise 'Identity drift '+p unless sha.call(p)==h}
 binaries=r['identities'].reject{|p,_|p.end_with?('.rb')};identities= binaries if identities.empty?;raise 'Different baselines' unless identities==binaries
 r['sources'].each{|h,s|raise 'Source hash' unless Digest::SHA256.hexdigest(s)==h}
 key=->(x){x.values_at('shape','width','snapshot','calls','mode')}
 raise 'Allocation coverage '+label unless r['rows'].map{|x|key.call(x)}.sort==shapes.product([128,2048],%w[once fresh],[16,32],%w[vm jit]).sort
 raise 'Semantics coverage '+label unless r['semantics'].map{|x|key.call(x)}.sort==shapes.product([128,2048],%w[once fresh],[16,32],%w[vm interpreter jit]).sort&&r['semantics'].all?{|x|x['exit']==0}
 (r['rows']+r['semantics']).each{|x|raise 'Missing fixture' unless %w[source_sha256 module_sha256].all?{|k|r['sources'].key?(x[k])}}
 r['rows'].each do |allocation|
  matches=r['semantics'].select{|x|x.values_at('shape','width','snapshot','calls')==allocation.values_at('shape','width','snapshot','calls')}
  raise 'Semantic fixture mismatch '+label unless matches.size==3&&matches.all?{|x|x.values_at('source_sha256','module_sha256')==allocation.values_at('source_sha256','module_sha256')}
 end
 deltas=r['rows'].group_by{|x|x.values_at('shape','width','snapshot','mode')}.map do |k,v|
  a,b=v.sort_by{|x|x['calls']};raise 'Module changed by calls' unless a['module_sha256']==b['module_sha256']
  delta=r['deltas'].find{|x|x.values_at('shape','width','snapshot','mode')==k};raise 'Missing delta' unless delta
  %w[requests bytes].each{|m|raise 'Delta mismatch' unless delta[m+'_per_added_call']==(b[m]-a[m])/16.0}
  delta.merge('variant'=>label)
 end
 raise 'Duplicate deltas' unless r['deltas'].size==deltas.size
 rows.concat(deltas);totals[:allocation]+=r['rows'].size;totals[:semantics]+=r['semantics'].size
end
penalties=rows.group_by{|x|x.values_at('variant','shape','snapshot','mode')}.map do |k,v|
 a,b=v.sort_by{|x|x['width']};{variant:k[0],shape:k[1],snapshot:k[2],mode:k[3],small_writes_per_call:a['writes_per_call'],large_writes_per_call:b['writes_per_call'],width_penalty_requests:b['requests_per_added_call']-a['requests_per_added_call'],width_penalty_bytes:b['bytes_per_added_call']-a['bytes_per_added_call']}
end
File.write(d+'/current-control-factor-results.json',JSON.pretty_generate({status:'characterized',counts:totals,baseline_identities:identities,slopes:rows,width_penalties:penalties,report_hashes:variants.keys.to_h{|k|[k,sha.call(d+'/current-'+k+'/report.json')]},verifier_sha256:sha.call(__FILE__),limits:'Counter controls remove both its captured write and return read, replacing them with a primitive parameter. Direct-loop controls change diagnostic expression form while preserving asserted final values. Dense work grows with width; fresh snapshots retain necessary copying. No candidate or elapsed-speed acceptance.'})+"\n")
puts 'Collection factor matrix independently verified'
